export type CurveStyles = zod.input<typeof CurveStyles>;
export type CurveStylesOutput = zod.output<typeof CurveStyles>;

export const CurveMultiStepDefault = 0;
export const CurveMultiStep = zod.union([zod.literal(0),zod.literal(1)]).default(CurveMultiStepDefault).describe('Multi-step block indicator for a bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve style: curve style is the quantity structure, this is the time structure, and they compose.')

export type CurveMultiStep = zod.input<typeof CurveMultiStep>;
export type CurveMultiStepOutput = zod.output<typeof CurveMultiStep>;

