export const EnergyUnitBasis = zod.enum(['MWH', 'MWMIN']).describe('Unit basis a stored-energy quantity is recorded in (distinct from EnergyUnit, which names fuel energy content). MWH: megawatt-hours, the conventional interchange form. MWMIN: megawatt-minutes, consistent with the minutes basis used for operational durations, so a duration computed as energy over power comes out in minutes with no hidden factor of 60. Defaults to MWH: MWMIN is supported, not preferred.')

export type EnergyUnitBasis = zod.input<typeof EnergyUnitBasis>;
export type EnergyUnitBasisOutput = zod.output<typeof EnergyUnitBasis>;

export const ImpedanceUnitBasis = zod.enum(['NATURAL_UNITS', 'COMPONENT_BASE']).describe('Unit basis a branch/injection impedance is stored in. NATURAL_UNITS: physical ohms (PSS/E RAW native for DC-line impedances). COMPONENT_BASE: per-unit on the component\'s own base (base_power MVA and voltage base); components whose per-unit data was historically on the system base record that system base in base_power, so there is no separate system-base option. PSS/E supplies device base for DC-line converters and CZ=2 transformer windings. A branch\'s shunt admittance halves (b, g) share the branch\'s one basis: NATURAL_UNITS stores them in siemens.')

export type ImpedanceUnitBasis = zod.input<typeof ImpedanceUnitBasis>;
export type ImpedanceUnitBasisOutput = zod.output<typeof ImpedanceUnitBasis>;

export const AdmittanceUnitBasis = zod.enum(['NATURAL_UNITS', 'COMPONENT_MVAR', 'COMPONENT_BASE']).describe('Unit basis a shunt admittance is stored in. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance). COMPONENT_BASE: per-unit on the component\'s own base (base_power MVA and voltage base) — a per-unit base, not a power at unity voltage, and not an alternative spelling of COMPONENT_MVAR; components whose per-unit data was historically on the system base record that system base in base_power. Fixed and switched shunts use ShuntAdmittanceUnitBasis instead, which omits COMPONENT_BASE because a shunt has no device MVA rating.')

export type AdmittanceUnitBasis = zod.input<typeof AdmittanceUnitBasis>;
export type AdmittanceUnitBasisOutput = zod.output<typeof AdmittanceUnitBasis>;

export const ShuntAdmittanceUnitBasis = zod.enum(['NATURAL_UNITS', 'COMPONENT_MVAR']).describe('Subset of AdmittanceUnitBasis for fixed and switched shunts: omits COMPONENT_BASE because a shunt has no device MVA rating to per-unitize against. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance) — PSS/E RAW native for shunts.')

export type ShuntAdmittanceUnitBasis = zod.input<typeof ShuntAdmittanceUnitBasis>;
export type ShuntAdmittanceUnitBasisOutput = zod.output<typeof ShuntAdmittanceUnitBasis>;

