export type PiecewiseStepDataOutput = zod.output<typeof PiecewiseStepData>;

export const quadraticFunctionDataFunctionTypeDefault = `QUADRATIC`;
export const QuadraticFunctionData = zod.object({
  "constant_term": zod.number(),
  "function_type": zod.enum(['QUADRATIC']).default(quadraticFunctionDataFunctionTypeDefault),
  "proportional_term": zod.number(),
  "quadratic_term": zod.number()
}).describe('Data for a quadratic function `f(x) = quadratic_term * x^2 + proportional_term * x + constant_term`. A non-negative `quadratic_term` makes the function convex.')

export type QuadraticFunctionData = zod.input<typeof QuadraticFunctionData>;
export type QuadraticFunctionDataOutput = zod.output<typeof QuadraticFunctionData>;

export const timeSeriesLinearFunctionDataFunctionTypeDefault = `TIME_SERIES_LINEAR`;
export const TimeSeriesLinearFunctionData = zod.object({
  "function_type": zod.enum(['TIME_SERIES_LINEAR']).default(timeSeriesLinearFunctionDataFunctionTypeDefault),
  "association_id": zod.int().describe('Store-minted id of the time series association whose values supply this function data over time. Resolved against the accompanying time series store on read; minted by that store and meaningful only against it, never assigned by a document producer.')
}).describe('Time-series-backed variant of `LinearFunctionData`. In place of inline coefficients it carries `association_id`, referencing a stored series that supplies them at each step; use it when the coefficients change over time.')

export type TimeSeriesLinearFunctionData = zod.input<typeof TimeSeriesLinearFunctionData>;
export type TimeSeriesLinearFunctionDataOutput = zod.output<typeof TimeSeriesLinearFunctionData>;

export const timeSeriesPiecewiseLinearDataFunctionTypeDefault = `TIME_SERIES_PIECEWISE_LINEAR`;
